    def sin(z):
        z = (z + 3.141592653589793) % 6.283185307179586 - 3.141592653589793
        term = z
        out = z
        for j in range(1,12):
            term *= -z*z/((2*j)*(2*j+1))
            out += term
        return out
    def tanh(z):
        e = 2.718281828459045**(2*z)
        return (e-1)/(e+1)
    def sf(s, spec):
        x,y = s
        r2 = x*x+y*y
        kind = spec[0]
        if kind == 'linear':
            return [x,y]
        if kind == 'affine':
            return [x,y,1.0]
        if kind == 'radial_cubic':
            return [x,y,r2*x,r2*y]
        if kind == 'component_cubic':
            return [x,y,x*x*x,y*y*y]
        if kind == 'quadratic':
            return [x,y,1.0,x*x,x*y,y*y]
        if kind == 'x_polynomial':
            return [x,y,x*x,x*x*x]
        if kind == 'mixed_polynomial':
            return [x,y,x*x,x*y,x*x*x,x*x*y]
        if kind == 'sine':
            k = spec[1]
            return [x,y,sin(k*x),sin(k*y)]
        if kind == 'tanh':
            k = spec[1]
            return [x,y,tanh(k*x),tanh(k*y)]
        k,w = spec[1],spec[2]
        angle = w*r2
        sn,cs = sin(angle),sin(angle+1.5707963267948966)
