        u,v = a
        kind,k = spec
        if kind == 'linear':
            return [u,v]
        if kind == 'tanh':
            return [tanh(k*u)/k,tanh(k*v)/k]
        if kind == 'sine':
            return [sin(k*u)/k,sin(k*v)/k]
